export const DS7_TOKEN_NAMES = Object.keys(DS7_TOKENS) as DsTokenName[]

export function dsToken(name: DsTokenName, theme: DsTheme = 'light'): string | number {
  const t = DS7_TOKENS[name]
  const v = t[theme]
  if (typeof v === 'number') return t.unit === 'px' ? `${v}px` : t.unit === 'ms' ? `${v}ms` : v
  return v
}

export const DS7_GRADIENT_UTILITY = "ds-text-gradient-brand" as const
export const DS7_SYNTAX_LANGUAGES = ["JavaScript","TypeScript","JSX","TSX","JSON","JSONC","HTML","CSS","SCSS","Bash","Shell","cURL","Python","Go","Java","Rust","SQL","YAML","TOML","Markdown","MDX","XML","GraphQL","Dockerfile","Diff","Plain Text"] as const
